&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot; data-start=&quot;1671&quot; data-end=&quot;1757&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Coordinate and integrate patient care across clinicians, caregivers, and providers&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot; data-start=&quot;1758&quot; data-end=&quot;1830&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Manage physician orders, documentation, and workflows within the EMR&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot; data-start=&quot;1831&quot; data-end=&quot;1910&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Partner with Intake to support timely admissions and reduce referral delays&lt;/span&gt;&lt;/li&gt;
